下面的零比特填充实现有误，导致某些数据仍会与定界符 `01111110` 混淆。请指出问题并给出修正。

```c
int ones = 0;
for (int i = 0; bits[i]; i++) {
    out[m++] = bits[i];
    if (bits[i] == '1') {
        ones++;
        if (ones == 6) { out[m++] = '0'; ones = 0; }  /* 问题在这 */
    } else ones = 0;
}
```

answer.code:
def bit_stuff(bits: str) -> str:
    """发送方：每出现 5 个连续 1，立即插入一个 0。"""
    out, ones = [], 0
    for b in bits:
        out.append(b)
        if b == '1':
            ones += 1
            if ones == 5:          # 恰好 5 个就插，不等第 6 个
                out.append('0')
                ones = 0
        else:
            ones = 0
    return ''.join(out)


def bit_unstuff(bits: str) -> str:
    """接收方：每见到 5 个连续 1，就把紧跟的那个 0 删掉（严格镜像）。"""
    out, ones, i = [], 0, 0
    while i < len(bits):
        out.append(bits[i])
        if bits[i] == '1':
            ones += 1
            if ones == 5:
                i += 1             # 跳过被插入的 0
                ones = 0
        else:
            ones = 0
        i += 1
    return ''.join(out)


data = '01111110101111111'
stuffed = bit_stuff(data)
back = bit_unstuff(stuffed)
print('原始   :', data, '(%d bit)' % len(data))
print('填充后 :', stuffed, '(%d bit)' % len(stuffed))
print('还原后 :', back, '(%d bit)' % len(back))
print('一致   :', back == data)
print('填充率 : %.1f%%' % (100.0 * (len(stuffed) - len(data)) / len(data)))

def crc_remainder(data: str, g: str) -> str:
    """模 2 除法求余数：data 末尾补 len(g)-1 个 0。"""
    r = len(g) - 1
    bits = [int(c) for c in data] + [0] * r
    gen = [int(c) for c in g]
    for i in range(len(data)):
        if bits[i]:                       # 最高位为 1 才除
            for j in range(len(gen)):
                bits[i + j] ^= gen[j]
    return ''.join(str(b) for b in bits[-r:])


def encode(data: str, g: str) -> str:
    return data + crc_remainder(data, g)


def check(frame: str, g: str) -> bool:
    r = len(g) - 1
    bits = [int(c) for c in frame]        # 不再补 0，直接对整帧取余
    gen = [int(c) for c in g]
    for i in range(len(frame) - r):
        if bits[i]:
            for j in range(len(gen)):
                bits[i + j] ^= gen[j]
    return all(b == 0 for b in bits[-r:])


G = '10011'                    # x^4 + x + 1
for data in ['1101011011', '101110', '1101']:
    frame = encode(data, G)
    print('D=%-12s FCS=%-5s 帧=%-16s 校验=%s'
          % (data, crc_remainder(data, G), frame, check(frame, G)))
print('注入 1 位错误后校验:', check('1101011011' + '1111', G))
